static void show(const char *name, const void *p, int n) {
    const unsigned char *b = (const unsigned char *)p;
    unsigned sum = 0;
    printf("%s:", name);
    for (int i = 0; i < n; i++) {
        if (n <= 16) {
            printf(" %d", b[i]);
        }
        sum = sum * 31u + b[i];
    }
    printf(" (n=%d sum=%u)\n", n, sum);
}

static int classify(int c) {
    switch (c) {
    case '\0': return 1;
    case '\a': return 2;
    case '\v': return 3;
    case '\x7f': return 4;
    case '\033': return 5;
    case '\xff': return 6;
    default: return 0;
    }
}

int main(void) {
    char local_row[8] = "m\0n";
    char padded[12] = "\0\0p";
    const char *joined = "ab\0" "cd";
    const char *octal_split = "\0" "12";
    const char *hex_split = "\x0" "f";
    const char *high = "\x80\xc3\xa9\xfe\xff";
    show("with_nuls", with_nuls, (int)sizeof("ab\0cd\0\0e"));
    show("global_row", global_row, (int)sizeof global_row);
    show("exact", exact, (int)sizeof exact);
    show("cut", cut, (int)sizeof cut);
    show("local_row", local_row, (int)sizeof local_row);
    show("padded", padded, (int)sizeof padded);
    show("joined", joined, (int)sizeof("ab\0" "cd"));
    show("octal_split", octal_split, (int)sizeof("\0" "12"));
    show("hex_split", hex_split, (int)sizeof("\x0" "f"));
    show("high", high, 6);
    for (int i = 0; i < 3; i++) {
        show("table", tables[i], table_len[i]);
    }
    show("all_bytes", all_bytes, (int)sizeof all_bytes);
    show("all_row", all_row, (int)sizeof all_row);
    show("all_ptr", all_ptr, 257);
    show("no_nul", no_nul, (int)sizeof no_nul);
    int bad = 0;
    for (int i = 0; i < 256; i++) {
        bad += (unsigned char)all_bytes[i] != i;
        bad += all_row[i] != i;
        bad += (unsigned char)all_ptr[i] != i;
        bad += i > 0 && no_nul[i - 1] != i;
    }
    printf("sizes %d %d %d %d %d\n", (int)strlen((const char *)no_nul), (int)sizeof("a\0b"), (int)strlen("a\0b"), (int)strlen(with_nuls), (int)strlen(with_nuls + 3));
    printf("chars %d %d %d %d %d %d %d\n", '\0', '\a', '\v', '\x7f', '\033', '\xff', '\x01');
    int kinds = 0;
    for (int i = 0; i < 256; i++) {
        kinds = kinds * 7 + classify(i);
        kinds %= 1000003;
    }
    printf("bad %d kinds %d\n", bad, kinds);
    return bad;
}
